import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import { combineUrl, urlToAction } from 'kea-router'

import api from 'lib/api'
import { userLogic } from 'scenes/userLogic'

import { PrevalidatedInvite } from '~/types'

export enum ErrorCodes {
    InvalidInvite = 'invalid_invite',
    InvalidRecipient = 'invalid_recipient',
    UserAlreadyMember = 'user_already_member',
    Unknown = 'unknown',
}

export interface ErrorInterface {
    code: ErrorCodes
    detail?: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inviteSignupLogicValues {
    acceptedInvite: null
    acceptedInviteLoading: boolean
    error: ErrorInterface | null
    invite: PrevalidatedInvite | null
    inviteLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inviteSignupLogicActions {
    acceptInvite: () => any
    acceptInviteFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    acceptInviteSuccess: (
        acceptedInvite: Promise<null> | null,
        payload?: any
    ) => {
        acceptedInvite: Promise<null> | null
        payload?: any
    }
    prevalidateInvite: (id: string) => string
    prevalidateInviteFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    prevalidateInviteSuccess: (
        invite: PrevalidatedInvite | null,
        payload?: string
    ) => {
        invite: PrevalidatedInvite | null
        payload?: string
    }
    setError: (payload: ErrorInterface) => {
        payload: ErrorInterface
    }
}

export type inviteSignupLogicType = MakeLogicType<inviteSignupLogicValues, inviteSignupLogicActions>

export const inviteSignupLogic = kea<inviteSignupLogicType>([
    path(['scenes', 'authentication', 'invite-signup', 'inviteSignupLogic']),
    actions({
        setError: (payload: ErrorInterface) => ({ payload }),
    }),
    reducers({
        error: [
            null as ErrorInterface | null,
            {
                setError: (_, { payload }) => payload,
            },
        ],
    }),
    loaders(({ actions, values }) => ({
        invite: [
            null as PrevalidatedInvite | null,
            {
                prevalidateInvite: async (id: string, breakpoint) => {
                    breakpoint()

                    try {
                        return await api.get(`api/signup/${id}/`)
                    } catch (e: any) {
                        if (e.status === 400) {
                            if (e.code === 'invalid_recipient') {
                                actions.setError({ code: ErrorCodes.InvalidRecipient, detail: e.detail })
                            } else if (e.code === 'user_already_member') {
                                actions.setError({ code: ErrorCodes.UserAlreadyMember, detail: e.detail })
                            } else if (e.code === 'account_exists') {
                                location.href = e.detail
                            } else {
                                actions.setError({ code: ErrorCodes.InvalidInvite, detail: e.detail })
                            }
                        } else {
                            actions.setError({ code: ErrorCodes.Unknown })
                        }
                        return null
                    }
                },
            },
        ],
        acceptedInvite: [
            null,
            {
                acceptInvite: () => {
                    if (!values.invite) {
                        return null
                    }
                    return api.create(`api/signup/${values.invite.id}/`)
                },
            },
        ],
    })),
    listeners({
        prevalidateInviteSuccess: ({ invite }) => {
            // An invite reaches an account through the identity provider, which needs the invite in
            // its session to admit the new member. Signed-in visitors accept it in the scene instead.
            if (invite && !userLogic.values.user) {
                location.href = combineUrl('/login/oidc/', { invite_id: invite.id }).url
            }
        },
    }),
    urlToAction(({ actions }) => ({
        '/signup/*': ({ _: id }, { error_code, error_detail }) => {
            if (error_code) {
                if ((Object.values(ErrorCodes) as string[]).includes(error_code)) {
                    actions.setError({ code: error_code as ErrorCodes, detail: error_detail })
                } else {
                    actions.setError({ code: ErrorCodes.Unknown, detail: error_detail })
                }
            } else if (id) {
                actions.prevalidateInvite(id)
            }
        },
    })),
])
